import pandas as pd

def find_overlapping_shifts(employee_shifts: pd.DataFrame) -> pd.DataFrame:
    if employee_shifts.empty:
        return pd.DataFrame(columns=['employee_id', 'max_overlapping_shifts', 'total_overlap_duration'])

    employee_shifts['start_time'] = pd.to_datetime(employee_shifts['start_time'])
    employee_shifts['end_time'] = pd.to_datetime(employee_shifts['end_time'])

    results = []
    for emp_id, group in employee_shifts.groupby('employee_id'):
        times = sorted(list(set(group['start_time'].tolist() + group['end_time'].tolist())))
        max_overlap = 1
        total_duration = 0
        for i in range(len(times) - 1):
            t_start = times[i]
            t_end = times[i + 1]
            dur_mins = (t_end - t_start).total_seconds() / 60.0
            cnt = sum((group['start_time'] <= t_start) & (group['end_time'] >= t_end))
            if cnt > max_overlap:
                max_overlap = cnt
            pairs = cnt * (cnt - 1) // 2
            total_duration += pairs * dur_mins
        results.append({
            'employee_id': emp_id,
            'max_overlapping_shifts': max_overlap,
            'total_overlap_duration': int(total_duration)
        })

    res_df = pd.DataFrame(results)
    return res_df.sort_values(by='employee_id', ascending=True)
